  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Honesty and Integrity$j$, $j${"readings": [{"title": "Ephesians 4 (King James Version)", "url": "/portal/bible/Ephesians/4"}], "body": "Honesty means telling the truth and not deceiving others by words or actions. Integrity means being the same person in public and in private, so that your actions match your values. God is a God of truth, and Jesus is the way, the truth and the life. Proverbs 12:22 says, Lying lips are abomination to the LORD: but they that deal truly are his delight. Ephesians 4:25 says, Wherefore putting away lying, speak every man truth with his neighbour: for we are members one of another. Lies break trust, and trust holds families, churches, schools and nations together.\n\nDishonesty takes many forms: lying, cheating on tests, plagiarism (presenting another person's words or ideas as your own), false excuses, exaggeration, gossip and keeping silent when the truth is needed. Today it also includes fake online profiles, altered images and misusing artificial intelligence to submit work you did not do. Honest work means giving credit, doing your own thinking and being open about help you received.\n\nTelling the truth is not always easy. Ephesians 4:15 calls us to speak the truth in love, which means being honest and kind together. Truth should be told with care, not as a weapon. Rahab, Daniel and Joseph show that integrity may cost something but God honors it.\n\nWorked example: you get a higher test score than you earned because the teacher added points by mistake. Tell the teacher. Common mistake: believing a small lie does not matter. Small lies train the heart to accept larger ones.\n\nYour task: (1) Define honesty and integrity. (2) List four forms of dishonesty at school. (3) Write how you would tell a hard truth in love.\n\nFlorida standards: NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1", "script": "Welcome back. Listen, a person of integrity is the same in public and in private.\n\nHonesty means telling the truth and not deceiving by words or actions. Integrity means your actions match your values. God is a God of truth. Proverbs 12:22 says, Lying lips are abomination to the LORD: but they that deal truly are his delight. Ephesians 4:25 says, speak every man truth with his neighbour: for we are members one of another.\n\nNow watch this. Dishonesty has many forms: lying, cheating, plagiarism, false excuses, exaggeration, gossip, and staying silent when truth is needed. Today it also includes fake profiles, altered images and using artificial intelligence to submit work you did not do. Honest work gives credit, does its own thinking and is open about help received.\n\nEphesians 4:15 says to speak the truth in love. Be honest and kind together. Truth should never be a weapon.\n\nSmall lies train the heart to accept larger ones.\n\nYour task is to define honesty and integrity, list four forms of dishonesty and write how you would tell a hard truth in love. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Honesty and Integrity$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Purity, Self Control and the Body$j$, $j${"readings": [{"title": "Philippians 4 (King James Version)", "url": "/portal/bible/Philippians/4"}], "body": "Scripture teaches that our bodies belong to God. 1 Corinthians 6:19 and 20 says, What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own? For ye are bought with a price: therefore glorify God in your body, and in your spirit, which are God's. Purity means keeping our thoughts, words, bodies and relationships clean and set apart for God. Self control, also called temperance, is a fruit of the Spirit and the ability to govern desires instead of being ruled by them.\n\nPurity begins in the mind. Philippians 4:8 says, whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report; if there be any virtue, and if there be any praise, think on these things. What we watch, hear and read shapes what we desire. Choose entertainment, friendships and technology that build purity.\n\nGod made sexual intimacy as a gift for marriage between a man and a woman, and Scripture calls believers to flee fornication (1 Corinthians 6:18). Boundaries, accountability, prayer and wise friends help. Those who have failed can be forgiven and restored, for 1 John 1:9 says that if we confess our sins, he is faithful and just to forgive us our sins. Pornography, abuse and exploitation harm people made in God's image and must be rejected.\n\nSelf control also applies to food, sleep, screens, spending and anger. Proverbs 25:28 says that he that hath no rule over his own spirit is like a city that is broken down, and without walls.\n\nWorked example: before a party, set your limits, arrange a ride and choose a friend to hold you accountable. Common mistake: waiting until temptation to decide. Decide ahead.\n\nYour task: (1) Define purity and self control. (2) List three boundaries that protect purity. (3) Write a plan for one area where you need more self control.\n\nFlorida standards: NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1", "script": "Welcome back. Listen, your body belongs to God, and purity is one way we honor Him.\n\nFirst Corinthians 6:19 and 20 says, your body is the temple of the Holy Ghost, and ye are not your own: for ye are bought with a price: therefore glorify God in your body. Purity means keeping our thoughts, words, bodies and relationships clean and set apart for God. Self control is a fruit of the Spirit. It is the ability to govern desires instead of being ruled by them.\n\nNow watch this. Purity begins in the mind. Philippians 4:8 says to think on whatsoever things are true, honest, just, pure and lovely. What we watch, hear and read shapes what we desire. Choose entertainment, friends and technology that build purity.\n\nGod made sexual intimacy as a gift for marriage, and Scripture calls us to flee fornication. Boundaries, accountability, prayer and wise friends help. If you have failed, 1 John 1:9 promises forgiveness to those who confess. Pornography, abuse and exploitation harm people made in God's image.\n\nSelf control also applies to food, sleep, screens, spending and anger. Decide ahead of temptation.\n\nYour task is to define purity and self control, list three boundaries and write a plan for one area. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Purity, Self Control and the Body$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Money, Work and Stewardship$j$, $j${"readings": [{"title": "Colossians 3 (King James Version)", "url": "/portal/bible/Colossians/3"}], "body": "Stewardship means managing what God has given us, including time, talents, money and possessions, in ways that honor Him. Psalm 24:1 says, The earth is the LORD'S, and the fulness thereof. We own nothing in the final sense. We manage it for God. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. Work is not a punishment. It is a way to serve God and others.\n\nEthical work means giving an honest day's effort, keeping your word, paying fair wages and refusing to steal or cheat. Stealing includes theft from stores, taking time on the job, pirating music or software, and fraud. Proverbs 11:1 says, A false balance is abomination to the LORD: but a just weight is his delight. Employers must treat workers justly, and workers must serve faithfully (Colossians 4:1).\n\nMoney handled well blesses others. Give generously, save wisely, avoid unnecessary debt and plan before spending. Proverbs 22:7 says, The rich ruleth over the poor, and the borrower is servant to the lender. 1 Timothy 6:10 says, the love of money is the root of all evil. Money is a tool, not a master, and contentment frees the heart (Hebrews 13:5). Jesus taught about faithful stewards in the parable of the talents in Matthew 25.\n\nWorked example: you are paid in cash for a job and could hide it. Report it honestly and give your tithe first. Common mistake: thinking that stewardship is only about money. It includes your time, gifts and body.\n\nYour task: (1) Define stewardship. (2) List three ways workers and employers act ethically. (3) Plan how you will give, save and spend one hundred dollars.\n\nFlorida standards: NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1", "script": "Welcome back. Listen, everything we have belongs to God. We are managers, not owners.\n\nPsalm 24:1 says, The earth is the LORD'S, and the fulness thereof. Stewardship means managing our time, talents, money and possessions in ways that honor Him. Work is not a punishment. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men.\n\nNow watch this. Ethical work means an honest day's effort, keeping your word, paying fair wages and refusing to steal or cheat. Stealing includes theft from stores, wasting time on the job, pirating music and fraud. Proverbs 11:1 says, A false balance is abomination to the LORD: but a just weight is his delight.\n\nMoney handled well blesses others. Give generously, save wisely, avoid unnecessary debt and plan before spending. Proverbs 22:7 says, the borrower is servant to the lender. Money is a tool, not a master. Hebrews 13:5 teaches contentment. In Matthew 25, Jesus taught about faithful stewards.\n\nStewardship includes your time, gifts and body, not only money.\n\nYour task is to define stewardship, list three ethical work practices and plan how to give, save and spend one hundred dollars. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Money, Work and Stewardship$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Words, Anger and Forgiveness$j$, $j${"readings": [{"title": "James 3 (King James Version)", "url": "/portal/bible/James/3"}], "body": "Words have power. Proverbs 18:21 says, Death and life are in the power of the tongue. James 3 compares the tongue to a small rudder that steers a large ship and to a spark that can burn a forest. Ethical speech avoids lying, gossip, slander (false or harmful statements), cursing, mocking and flattery. It builds up. Ephesians 4:29 says, Let no corrupt communication proceed out of your mouth, but that which is good to the use of edifying, that it may minister grace unto the hearers. Online, words last. Before posting, ask: Is it true? Is it kind? Is it necessary?\n\nAnger is a human emotion, not always sin. Ephesians 4:26 says, Be ye angry, and sin not: let not the sun go down upon your wrath. Anger becomes sin when it leads to revenge, hatred or harm. James 1:19 and 20 says, let every man be swift to hear, slow to speak, slow to wrath: for the wrath of man worketh not the righteousness of God. Proverbs 15:1 says, A soft answer turneth away wrath: but grievous words stir up strife. Calm down, pray, listen, then speak.\n\nForgiveness means releasing a debt and choosing not to take revenge. Ephesians 4:32 says, And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ's sake hath forgiven you. Forgiveness does not excuse wrong or require unsafe contact, and trust may need time to rebuild. If you are being harmed, tell a trusted adult. Reconciliation requires both people. Jesus taught in Matthew 18:15 to go to a brother privately when he sins against you.\n\nWorked example: a friend repeated a rumor about you. Pray, wait until you are calm, speak privately, and forgive. Common mistake: venting online. Handle conflict face to face when safe.\n\nYour task: (1) Define slander and gossip. (2) List three steps to handle anger. (3) Write how you would forgive and seek peace in a real conflict.\n\nFlorida standards: NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1", "script": "Welcome back. Listen, words can heal or wound, and God holds us responsible for how we use them.\n\nProverbs 18:21 says, Death and life are in the power of the tongue. James 3 compares the tongue to a small rudder that steers a big ship and to a spark that can burn a forest. Ethical speech avoids lying, gossip, slander, cursing and mocking. It builds up. Ephesians 4:29 says to let no corrupt communication proceed out of your mouth, but that which is good to the use of edifying. Online, words last. Ask: Is it true? Is it kind? Is it necessary?\n\nNow watch this. Anger is a human emotion, not always sin. Ephesians 4:26 says, Be ye angry, and sin not. Anger becomes sin when it leads to revenge or harm. Proverbs 15:1 says, A soft answer turneth away wrath. Calm down, pray, listen, then speak.\n\nForgiveness means releasing a debt and choosing not to take revenge. Ephesians 4:32 says to forgive, even as God for Christ's sake hath forgiven you. Forgiveness does not excuse wrong or require unsafe contact. If you are being harmed, tell a trusted adult. In Matthew 18, Jesus said to go to the person privately.\n\nYour task is to define slander and gossip, list three steps to handle anger and write how you would forgive. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Words, Anger and Forgiveness$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Personal Ethics$j$, $j${"prompt": "Write a report of at least 250 words on personal ethics. Use complete sentences and label each part. Do not include private details or names of real people. Proverbs 4:23 says, Keep thy heart with all diligence; for out of it are the issues of life.\n\nPart 1: Explain honesty and integrity and describe how you will practice them in schoolwork and online.\nPart 2: Explain purity and self control and describe three boundaries that protect them.\nPart 3: Explain stewardship and write a plan to give, save and spend a sample amount of money.\nPart 4: Explain how Christians should handle anger and speech and describe the steps of forgiveness.\nPart 5: Explain how the Holy Spirit helps believers live ethically.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 25 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Personal Ethics$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Truth in Love$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a time when telling the truth is hard for teens, (2) explains how to speak the truth in love, (3) names one habit that builds integrity, and (4) connects your answer to Ephesians 4:15 or Proverbs 12:22. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why does a small lie matter? Do not name real people or share private details."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Truth in Love$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Honesty and Integrity$j$, $j${"questions": [{"q": "Integrity means:", "options": ["Winning", "Your actions match your values in public and private", "Never making mistakes", "Being popular"]}, {"q": "Plagiarism is:", "options": ["Editing", "Presenting another person's work as your own", "Studying", "Giving credit"]}, {"q": "Ephesians 4:15 says to speak the truth:", "options": ["In love", "Only when angry", "To win", "Never"]}, {"q": "Small lies:", "options": ["Are always kind", "Never matter", "Train the heart to accept larger ones", "Build trust"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Honesty and Integrity$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,0,2}'::int[], array[$j$Integrity is consistency of character.$j$,$j$It is a form of stealing and lying.$j$,$j$Truth and love belong together.$j$,$j$Habits of dishonesty grow.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Honesty and Integrity$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Purity, Self Control and the Body$j$, $j${"questions": [{"q": "1 Corinthians 6:19 calls the body:", "options": ["A trophy", "The temple of the Holy Ghost", "A toy", "Unimportant"]}, {"q": "Purity begins in the:", "options": ["Closet", "Mind", "Calendar", "Wallet"]}, {"q": "Self control is a:", "options": ["Sport", "Fruit of the Spirit", "Punishment", "Talent"]}, {"q": "1 John 1:9 promises that God will:", "options": ["Ignore sin", "Punish forever", "Forgive those who confess", "Reject all failures"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Purity, Self Control and the Body$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,2}'::int[], array[$j$Our bodies belong to God.$j$,$j$What we think about shapes what we do.$j$,$j$Temperance is listed in Galatians 5.$j$,$j$He is faithful and just to forgive.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Purity, Self Control and the Body$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Money, Work and Stewardship$j$, $j${"questions": [{"q": "Stewardship means:", "options": ["Owning everything", "Managing what God has given us", "Ignoring work", "Hiding money"]}, {"q": "Psalm 24:1 says the earth is:", "options": ["Ours", "A mistake", "Nobody's", "The LORD'S"]}, {"q": "Which is a form of stealing?", "options": ["Pirating software", "Helping", "Saving money", "Giving credit"]}, {"q": "Money should be treated as:", "options": ["A god", "Evil in itself", "Meaningless", "A tool, not a master"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Money, Work and Stewardship$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,0,3}'::int[], array[$j$We manage on God's behalf.$j$,$j$Everything belongs to God.$j$,$j$Piracy takes what is not yours.$j$,$j$The love of money is the root of evil, not money itself.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Money, Work and Stewardship$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Words, Anger and Forgiveness$j$, $j${"questions": [{"q": "Proverbs 15:1 says a soft answer:", "options": ["Is weakness", "Turneth away wrath", "Starts a fight", "Is useless"]}, {"q": "Slander is:", "options": ["Prayer", "Debate", "Truthful praise", "False or harmful statements about someone"]}, {"q": "Forgiveness means:", "options": ["Allowing harm", "Releasing a debt and refusing revenge", "Forgetting at once", "Pretending nothing happened"]}, {"q": "Ephesians 4:26 says to be angry and:", "options": ["Seek revenge", "Hide it forever", "Shout", "Sin not"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Words, Anger and Forgiveness$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,1,3}'::int[], array[$j$Gentle words calm anger.$j$,$j$Slander damages a person's reputation.$j$,$j$It does not excuse harm.$j$,$j$Anger must not lead to sin.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Words, Anger and Forgiveness$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Personal Ethics$j$, $j${"questions": [{"q": "Integrity means:", "options": ["Being consistent in public and private", "Never being tested", "Being famous", "Hiding mistakes"]}, {"q": "Using artificial intelligence to submit work you did not do is:", "options": ["Honest", "Always allowed", "Required", "Dishonest"]}, {"q": "Which verse says your body is the temple of the Holy Ghost?", "options": ["Acts 2:4", "1 Corinthians 6:19", "Psalm 1:1", "Genesis 1:1"]}, {"q": "Philippians 4:8 teaches us to think on things that are:", "options": ["Rich and famous", "Secret", "True, pure and lovely", "Fast and loud"]}, {"q": "Stewardship means:", "options": ["Avoiding work", "Wasting resources", "Managing what belongs to God", "Owning it all"]}, {"q": "A just weight in Proverbs 11:1 refers to:", "options": ["Cooking", "Exercise", "Fair dealing", "Travel"]}, {"q": "James 1:19 says to be slow to:", "options": ["Listen", "Help", "Pray", "Speak and become wrathful"]}, {"q": "Forgiveness does not require:", "options": ["Releasing revenge", "Kindness", "Staying in an unsafe situation", "Prayer"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Personal Ethics$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,2,2,2,3,2}'::int[], array[$j$Integrity is consistent character.$j$,$j$It misrepresents who did the work.$j$,$j$Paul taught this to the Corinthians.$j$,$j$The mind shapes behavior.$j$,$j$We are managers for God.$j$,$j$God delights in honest business.$j$,$j$Slow to speak, slow to wrath.$j$,$j$Safety matters and a trusted adult can help.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Personal Ethics$j$ on conflict (item_id) do nothing;
